        "handsOnScenario": {
          "title": "Configuring and Verifying Configuration Management",
          "scenario": "You are tasked with implementing Configuration Management for a mission-critical payments service that requires high availability, automated safety checks, and deterministic promotion across staging and production.",
          "goal": "Construct an end-to-end automated pipeline configuration that validates code quality, executes hermetic tests, signs the resulting artifact, and deploys it safely.",
          "steps": [
            "Inspect the project structure and configure the declarative configuration file in your repository.",
            "Set up environment variables and configure secret injection using temporary token federation.",
            "Trigger the workflow using a test commit and inspect real-time runner execution logs.",
            "Simulate an upstream failure to verify that the automated failure gate halts deployment immediately."
          ]
        },
        "practicalChallenge": {
          "task": "Write a robust configuration snippet that validates Configuration Management, verifies container image integrity, and triggers an automated alert if execution exceeds 300 seconds.",
          "hint": "Combine timeout-minutes with strict exit code validation and post-failure notification webhooks.",
          "solution": "# Production-grade verification step\n- name: Verify Configuration Management Health\n  timeout-minutes: 5\n  run: |\n    echo \"Running compliance checks...\"\n    ./scripts/verify-compliance.sh --strict\n    echo \"Checks passed successfully.\""
        },
